"""Build the offline demo Golden Snapshot.

IMPORTANT: the companies below are FICTITIOUS (tickers 99000x, names prefixed
"演示"). Their numbers are generated by a seeded, internally consistent model so
the whole system can run offline and every benchmark has a computable ground
truth. They are not market data. Use `scripts/ingest_live.py` (AKShare) to
build a snapshot of real A-share companies when network access is available.

Outputs (benchmarks/golden_snapshot/):
  securities.csv, financial_facts.csv, market_prices.csv, documents.csv,
  documents/*.md, rag_eval_v1.jsonl
"""
from __future__ import annotations

import csv
import hashlib
import json
from dataclasses import dataclass, field
from datetime import date, datetime, timedelta
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "benchmarks" / "golden_snapshot"
RETRIEVED_AT = datetime(2026, 4, 1, 10, 0)
YEARS = [2022, 2023, 2024, 2025]
TAX = 0.15


@dataclass
class Co:
    ticker: str
    name: str
    l1: str
    l2: str
    template: str
    base_rev: float
    growth: float
    gm: float
    opex: float
    ocf: float
    ar_days: float
    inv_days: float
    liab: float
    debt_share: float
    equity0: float
    goodwill: float
    shares: float
    price0: float
    vol: float
    seasonal: tuple = (0.9, 1.0, 1.05, 1.05)
    overrides: dict = field(default_factory=dict)  # t -> dict of param overrides


def t_of(y: int, q: int) -> int:
    return (y - 2022) * 4 + (q - 1)


