REPORT_SCHEDULE = {1: ("q1_report", "{y}-04-26"), 2: ("semi_annual_report", "{y}-08-25"),
                   3: ("q3_report", "{y}-10-28"), 4: ("annual_report", "{y1}-03-28")}
CUM_TYPE = {1: "cumulative_q1", 2: "cumulative_h1", 3: "cumulative_q3", 4: "annual"}
FLOW_METRICS = ["operating_revenue", "operating_cost", "rd_expense", "asset_impairment_loss",
                "net_profit", "operating_cash_flow"]
INSTANT_METRICS = ["accounts_receivable", "inventory", "total_assets", "total_liabilities",
                   "total_equity", "interest_bearing_debt", "goodwill", "cash", "shares_outstanding"]
CN = {"operating_revenue": "营业收入", "operating_cost": "营业成本", "rd_expense": "研发费用",
      "asset_impairment_loss": "资产减值损失", "net_profit": "归属于母公司股东的净利润",
      "operating_cash_flow": "经营活动产生的现金流量净额", "accounts_receivable": "应收账款", "inventory": "存货",
      "total_assets": "资产总计", "total_liabilities": "负债合计", "total_equity": "所有者权益合计",
      "interest_bearing_debt": "有息负债", "goodwill": "商誉", "cash": "货币资金", "shares_outstanding": "总股本"}


def next_weekday_open(d: date) -> datetime:
    n = d + timedelta(days=1)
    while n.weekday() >= 5:
        n += timedelta(days=1)
    return datetime(n.year, n.month, n.day, 9, 30)


def pub_times(y: int, q: int) -> tuple[str, datetime, datetime]:
    doc_type, tmpl = REPORT_SCHEDULE[q]
    d = date.fromisoformat(tmpl.format(y=y, y1=y + 1))
    published = datetime(d.year, d.month, d.day, 20, 0)
    return doc_type, published, next_weekday_open(d)


def period_end(y: int, q: int) -> date:
    return {1: date(y, 3, 31), 2: date(y, 6, 30), 3: date(y, 9, 30), 4: date(y, 12, 31)}[q]


def simulate(co: Co):
    """Return single-quarter flows and instants keyed by (y, q)."""
    rng = np.random.RandomState(int(co.ticker[:6]))
    flows, inst = {}, {}
    equity = co.equity0
    rev_hist = []
    cost_hist = []
    for y in YEARS:
        for q in range(1, 5):
            t = t_of(y, q)
            p = {"gm": co.gm, "opex": co.opex, "ocf": co.ocf, "ar_days": co.ar_days, "inv_days": co.inv_days,
                 "liab": co.liab, "debt_share": co.debt_share, "impairment": 0.0}
            p.update(co.overrides.get(t, {}))
            rev = co.base_rev * (1 + co.growth) ** (t / 4) * co.seasonal[q - 1] * (1 + rng.normal(0, 0.02))
            cost = rev * (1 - p["gm"])
            rd = rev * co.opex * 0.4
            routine_impair = rev * 0.003
            impairment = routine_impair + p["impairment"]
            pretax = rev - cost - rev * p["opex"] - impairment
            np_ = pretax * (1 - TAX) if pretax > 0 else pretax
            ocf = np_ * p["ocf"] if np_ > 0 else np_ * 0.5 + rev * 0.02
            equity += np_
            rev_hist.append(rev)
            cost_hist.append(cost)
            rev_ttm = sum(rev_hist[-4:]) * 4 / len(rev_hist[-4:])
            cost_ttm = sum(cost_hist[-4:]) * 4 / len(cost_hist[-4:])
            assets = equity / (1 - p["liab"])
            liabilities = assets - equity
            flows[(y, q)] = {"operating_revenue": rev, "operating_cost": cost, "rd_expense": rd,
                             "asset_impairment_loss": impairment, "net_profit": np_, "operating_cash_flow": ocf}
            inst[(y, q)] = {"accounts_receivable": rev_ttm * p["ar_days"] / 365,
                            "inventory": cost_ttm * p["inv_days"] / 365,
                            "total_assets": assets, "total_liabilities": liabilities, "total_equity": equity,
                            "interest_bearing_debt": liabilities * p["debt_share"], "goodwill": co.goodwill,
                            "cash": assets * 0.18, "shares_outstanding": co.shares}
    return flows, inst


def cumulative(flows, y, q):
    out = {}
    for m in FLOW_METRICS:
        out[m] = sum(flows[(y, k)][m] for k in range(1, q + 1))
    return out


def fmt_wan(v: float) -> str:
    return f"{v / 1e4:,.2f}"


def doc_id(ticker: str, y: int, q: int, version: int = 1) -> str:
    base = f"doc_{ticker[:6]}_{y}Q{q}"
    return base if version == 1 else f"{base}_v{version}"


def write_report(co: Co, y: int, q: int, cum: dict, prev_cum: dict | None, inst_now: dict, flows, scen_text: str) -> str:
    doc_type, published, _ = pub_times(y, q)
    title = {"q1_report": "第一季度报告", "semi_annual_report": "半年度报告",
             "q3_report": "第三季度报告", "annual_report": "年度报告"}[doc_type]
    pe = period_end(y, q)
    lines = [f"# {co.name}（{co.ticker}）{y}年{title}", "", "<!-- page 1 -->", "## 第一节 重要提示",
             f"本报告期截止日为{pe.isoformat()}。本报告为演示用虚构公司数据，不构成任何投资建议。", "",
             "<!-- page 2 -->", "## 第三节 管理层讨论与分析"]
    if prev_cum:
        rg = cum["operating_revenue"] / prev_cum["operating_revenue"] - 1
        ng = cum["net_profit"] / prev_cum["net_profit"] - 1 if prev_cum["net_profit"] > 0 else None
        og = cum["operating_cash_flow"] / prev_cum["operating_cash_flow"] - 1 if prev_cum["operating_cash_flow"] > 0 else None
        lines.append(f"报告期内，公司实现营业收入同比{'增长' if rg >= 0 else '下降'}{abs(rg) * 100:.2f}%。")
        if ng is not None:
            lines.append(f"归属于母公司股东的净利润同比{'增长' if ng >= 0 else '下降'}{abs(ng) * 100:.2f}%。")
        if og is not None:
            lines.append(f"经营活动产生的现金流量净额同比{'增长' if og >= 0 else '下降'}{abs(og) * 100:.2f}%。")
    lines += [scen_text, "", "<!-- page 3 -->", "## 第四节 财务报表", "### 合并利润表（单位：万元）",
              "| 项目 | 本期金额 |", "| --- | --- |"]
    for m in ["operating_revenue", "operating_cost", "rd_expense", "asset_impairment_loss"]:
        lines.append(f"| {CN[m]} | {fmt_wan(cum[m])} |")
    lines.append("<!-- page 4 -->")  # table crosses a page break on purpose
    for m in ["net_profit"]:
        lines.append(f"| {CN[m]} | {fmt_wan(cum[m])} |")
    lines += ["", "### 合并现金流量表（单位：万元）", "| 项目 | 本期金额 |", "| --- | --- |",
              f"| {CN['operating_cash_flow']} | {fmt_wan(cum['operating_cash_flow'])} |", "",
              "### 合并资产负债表（单位：万元）", "| 项目 | 期末余额 |", "| --- | --- |"]
    for m in ["cash", "accounts_receivable", "inventory", "goodwill", "total_assets", "total_liabilities", "total_equity"]:
        lines.append(f"| {CN[m]} | {fmt_wan(inst_now[m])} |")
    lines += ["", "<!-- page 5 -->", "### 母公司利润表（单位：万元）", "| 项目 | 本期金额 |", "| --- | --- |",
              f"| {CN['operating_revenue']} | {fmt_wan(cum['operating_revenue'] * 0.38)} |",
              f"| 净利润 | {fmt_wan(cum['net_profit'] * 0.30)} |", "",
              "<!-- page 6 -->", "## 第五节 财务报表附注", "### 应收账款：按欠款方归集的期末余额前五名（单位：万元）",
              "| 欠款方 | 期末余额 | 占应收账款比例 |", "| --- | --- | --- |"]
    ar = inst_now["accounts_receivable"]
    shares = [0.22, 0.15, 0.09, 0.06, 0.04]
    for i, s in enumerate(shares, 1):
        lines.append(f"| 客户{chr(64 + i)} | {fmt_wan(ar * s)} | {s * 100:.2f}% |")
    lines.append(f"前五名合计占应收账款期末余额的{sum(shares) * 100:.2f}%。")
    lines += ["", "### 存货跌价准备（单位：万元）", "| 项目 | 期末账面余额 | 跌价准备 |", "| --- | --- | --- |",
              f"| 原材料 | {fmt_wan(inst_now['inventory'] * 0.4)} | {fmt_wan(flows[(y, q)]['asset_impairment_loss'] * 0.5)} |",
              f"| 库存商品 | {fmt_wan(inst_now['inventory'] * 0.6)} | {fmt_wan(flows[(y, q)]['asset_impairment_loss'] * 0.5)} |",
              "", "<!-- page 7 -->", "## 第六节 风险因素",
              "公司面临行业竞争加剧、原材料价格波动、下游需求不及预期以及汇率波动等风险。"]
    return "\n".join(lines) + "\n"


