def main() -> None:
    (OUT / "documents").mkdir(parents=True, exist_ok=True)
    facts, docs, prices = [], [], []
    with open(OUT / "securities.csv", "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["ticker", "name", "list_date", "industry_sw_l1", "industry_sw_l2", "template", "is_demo"])
        for co in COMPANIES:
            w.writerow([co.ticker, co.name, "2015-06-10", co.l1, co.l2, co.template, "true"])

    def add_doc(ticker, did, title, doc_type, pe, published, text, version=1):
        p = OUT / "documents" / f"{did}.md"
        p.write_text(text, encoding="utf-8")
        docs.append({"document_id": did, "ticker": ticker, "title": title, "doc_type": doc_type,
                     "period_end": pe.isoformat() if pe else "", "published_at": published.isoformat(),
                     "available_at": next_weekday_open(published.date()).isoformat(),
                     "content_hash": hashlib.sha256(text.encode()).hexdigest(), "path": f"documents/{did}.md",
                     "version": version})

    for co in COMPANIES:
        flows, inst = simulate(co)
        for y in YEARS:
            for q in range(1, 5):
                doc_type, published, available = pub_times(y, q)
                pe = period_end(y, q)
                did = doc_id(co.ticker, y, q)
                cum = cumulative(flows, y, q)
                reliable = not (co.ticker == "990004.SH" and y == 2022 and q == 1)
                for m, v in cum.items():
                    facts.append(dict(ticker=co.ticker, metric=m, scope="consolidated", period_type=CUM_TYPE[q],
                                      value=v, period_end=pe, published=published, available=available,
                                      doc=did, rev=1, reliable=reliable, source="demo_filing"))
                for m, v in inst[(y, q)].items():
                    facts.append(dict(ticker=co.ticker, metric=m, scope="consolidated", period_type="instant",
                                      value=v, period_end=pe, published=published, available=available,
                                      doc=did, rev=1, reliable=reliable, source="demo_filing"))
                for m, share in (("operating_revenue", 0.38), ("net_profit", 0.30)):
                    facts.append(dict(ticker=co.ticker, metric=m, scope="parent", period_type=CUM_TYPE[q],
                                      value=cum[m] * share, period_end=pe, published=published, available=available,
                                      doc=did, rev=1, reliable=reliable, source="demo_filing"))
                if y >= 2024:
                    prev = cumulative(flows, y - 1, q)
                    text = write_report(co, y, q, cum, prev, inst[(y, q)], flows,
                                        SCENARIO_TEXT.get((co.ticker, y), DEFAULT_TEXT))
                    title = text.splitlines()[0].lstrip("# ")
                    add_doc(co.ticker, did, title, doc_type, pe, published, text)
        # secondary vendor with a conflicting value (data-conflict trap)
        if co.ticker == "990002.SZ":
            cum = cumulative(flows, 2025, 1)
            _, published, available = pub_times(2025, 1)
            facts.append(dict(ticker=co.ticker, metric="operating_revenue", scope="consolidated",
                              period_type="cumulative_q1", value=cum["operating_revenue"] * 1.03,
                              period_end=period_end(2025, 1), published=published, available=available,
                              doc=None, rev=1, reliable=True, source="demo_vendor_b"))
        # prices: anchored to fundamentals known at each date (target PE on TTM profit, or PB when
        # TTM profit <= 0) times a mean-reverting AR(1) sentiment factor
        rng = np.random.RandomState(int(co.ticker[:6]) + 7)
        known = []  # (available_at_date, ttm_np, equity)
        for y in YEARS:
            for q in range(1, 5):
                _, _, avail = pub_times(y, q)
                last4 = [k for k in sorted(flows) if k <= (y, q)][-4:]
                ttm = sum(flows[k]["net_profit"] for k in last4) * 4 / len(last4)
                known.append((avail.date(), ttm, inst[(y, q)]["total_equity"]))
        target_pe = {"990001.SZ": 22, "990002.SZ": 20, "990003.SH": 18, "990004.SH": 28, "990005.SZ": 15,
                     "990006.SZ": 25}[co.ticker]
        d = date(2022, 1, 3)
        x = 0.0
        px = None
        fair = None
        while d <= date(2026, 3, 31):
            if d.weekday() < 5:
                x = 0.98 * x + rng.normal(0, co.vol / np.sqrt(252))
                vis = [k for k in known if k[0] <= d] or known[:1]
                _, ttm, eq = vis[-1]
                target = max(target_pe * ttm, 0.6 * eq) / co.shares   # book-value floor for loss makers
                if co.ticker == "990001.SZ" and d >= date(2026, 1, 21):
                    target *= 0.8  # reaction to the (future) 立案 announcement
                fair = target if fair is None else fair + (target - fair) / 20  # ~1 month price discovery
                prev_px = px if px is not None else fair * np.exp(x)
                px = max(0.5, fair * np.exp(x))
                hi = max(px, prev_px) * (1 + abs(rng.normal(0, 0.008)))
                lo = min(px, prev_px) * (1 - abs(rng.normal(0, 0.008)))
                to = float(np.clip(rng.normal(1.2, 0.4), 0.2, 4.0))
                prices.append([co.ticker, d.isoformat(), round(prev_px, 2), round(hi, 2), round(lo, 2), round(px, 2),
                               round(co.shares * 0.8 * to / 100, 0), round(to, 4), round(px * co.shares, 2),
                               round(px * co.shares * 0.8, 2), datetime(d.year, d.month, d.day, 15, 0).isoformat()])
            d += timedelta(days=1)

    for ticker, did, title, published, body in ANNOUNCEMENTS:
        text = f"# {title}\n\n<!-- page 1 -->\n## 公告正文\n{body}\n"
        add_doc(ticker, did, title, "announcement", None, published, text)
    # 990002 restatement announcement (2024 H1 revenue)
    add_doc("990002.SZ", "ann_990002_20241210", "关于2024年半年度报告会计差错更正的公告", "announcement", None,
            datetime(2024, 12, 10, 20, 0),
            "# 关于2024年半年度报告会计差错更正的公告\n\n<!-- page 1 -->\n## 公告正文\n公司对2024年半年度营业收入确认时点进行更正，调减2024年1-6月营业收入18.00亿元。\n")

    # restated revisions
    by_key = {(f["ticker"], f["metric"], f["period_end"], f["scope"], f["source"]): f for f in facts}
    for ticker, y, q, metric, delta, published, did in RESTATEMENTS:
        base = by_key[(ticker, metric, period_end(y, q), "consolidated", "demo_filing")]
        facts.append({**base, "value": base["value"] + delta, "published": published,
                      "available": next_weekday_open(published.date()), "doc": did, "rev": 2})

    with open(OUT / "financial_facts.csv", "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["fact_id", "ticker", "metric", "statement_scope", "period_type", "value", "unit", "period_end",
                    "published_at", "available_at", "retrieved_at", "source", "source_document_id", "revision_id",
                    "is_restated", "published_at_reliable"])
        for x in facts:
            pe = x["period_end"]
            fid = f"fact_{x['ticker'][:6]}_{pe.strftime('%Y%m%d')}_{x['metric']}_{x['scope'][:3]}_{x['source'][-6:]}_v{x['rev']}"
            w.writerow([fid, x["ticker"], x["metric"], x["scope"], x["period_type"], f"{x['value']:.2f}", "CNY",
                        pe.isoformat(), x["published"].isoformat(), x["available"].isoformat(),
                        RETRIEVED_AT.isoformat(), x["source"], x["doc"] or "", x["rev"],
                        "true" if x["rev"] > 1 else "false", "true" if x["reliable"] else "false"])
    with open(OUT / "market_prices.csv", "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["ticker", "trade_date", "open", "high", "low", "close", "volume", "turnover_rate", "total_mv",
                    "float_mv", "available_at"])
        w.writerows(prices)
    with open(OUT / "documents.csv", "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=list(docs[0].keys()))
        w.writeheader()
        w.writerows(docs)

    rag_eval = []
    for co in COMPANIES:
        for (y, q) in [(2025, 3), (2025, 2), (2024, 4)]:
            did = doc_id(co.ticker, y, q)
            pl = f"{y}年" + {1: "第一季度报告", 2: "半年度报告", 3: "第三季度报告", 4: "年度报告"}[q]
            common = {"ticker": co.ticker, "as_of": "2025-12-31T15:00:00", "target_document_id": did,
                      "period": f"{y}Q{q}"}
            rag_eval += [
                {"query": f"{pl} 应收账款 前五名 欠款方", "target_section_contains": "应收账款：按欠款方归集", **common},
                {"query": f"{pl} 存货跌价准备 计提", "target_section_contains": "存货跌价准备", **common},
                {"query": f"{pl} 经营活动现金流量净额 变动原因 管理层讨论", "target_section_contains": "管理层讨论与分析", **common},
                {"query": f"{pl} 合并利润表 净利润", "target_section_contains": "合并利润表", **common},
            ]
    with open(OUT / "rag_eval_v1.jsonl", "w", encoding="utf-8") as f:
        for r in rag_eval:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    print(f"facts={len(facts)} prices={len(prices)} docs={len(docs)} rag_eval={len(rag_eval)} -> {OUT}")


if __name__ == "__main__":
    main()
